return ['domain'=>'wp-updates-notifier','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'de_DE','project-id-version'=>'WP Updates Notifier','pot-creation-date'=>'2026-01-01 00:00+0000','po-revision-date'=>'2026-01-01 00:00+0000','messages'=>['WP Updates Notifier'=>'WP Updates Notifier','https://wpun.cariss.dev/'=>'https://wpun.cariss.dev/','Sends an email to notify you if there are any updates for your WordPress site. Can notify about core, plugin and theme updates.'=>'Sendet dir eine E-Mail, wenn es Aktualisierungen für deine WordPress-Website gibt. Kann über Aktualisierungen von Core, Plugins und Themes benachrichtigen.','Scott Cariss'=>'Scott Cariss','https://wpun.cariss.dev/#about-the-developer'=>'https://wpun.cariss.dev/#about-the-developer','Enabled'=>'Aktiviert','Send notifications through this channel'=>'Benachrichtigungen über diesen Kanal senden','(external link)'=>'(externer Link)','About the plugin'=>'Über das Plugin','WP Updates Notifier checks your site for WordPress core, plugin and theme updates and tells you about each new version once. It is free and open source, with no tracking and no account to sign up for.'=>'WP Updates Notifier prüft deine Website auf Aktualisierungen für den WordPress-Core, Plugins und Themes und informiert dich einmal über jede neue Version. Es ist kostenlos und Open Source, ohne Tracking und ohne Konto, für das du dich registrieren musst.','Documentation'=>'Dokumentation','GitHub'=>'GitHub','WordPress.org'=>'WordPress.org','Help and bugs'=>'Hilfe und Fehler','Questions: ask in the %s.'=>'Fragen: Stelle sie im %s.','support forum'=>'Support-Forum','Bugs and ideas: open an issue on %s.'=>'Fehler und Ideen: Eröffne ein Issue auf %s.','Security problems: please report them privately, as the %s explains.'=>'Sicherheitsprobleme: Bitte melde sie vertraulich, wie in der %s beschrieben.','security policy'=>'Sicherheitsrichtlinie','Leave a review'=>'Bewertung schreiben','Like it? %s. It helps other people find the plugin.'=>'Gefällt es dir? %s. Das hilft anderen, das Plugin zu finden.','Leave a review on WordPress.org'=>'Schreib eine Bewertung auf WordPress.org','Donate'=>'Spenden','WP Updates Notifier is free. If it saves you time and you would like to say thanks, a donation helps keep it maintained.'=>'WP Updates Notifier ist kostenlos. Wenn es dir Zeit spart und du dich bedanken möchtest, hilft eine Spende dabei, es weiter zu pflegen.','Ways to donate'=>'Möglichkeiten zu spenden','About the developer'=>'Über den Entwickler','I have been a software engineer for over 20 years and I am now a Lead Platform Engineer, building the platforms other engineers ship on. I first released WP Updates Notifier on WordPress.org in 2011, and it now runs on around 30,000 sites.'=>'Ich bin seit über 20 Jahren Softwareentwickler und heute Lead Platform Engineer: Ich baue die Plattformen, auf denen andere Entwickler ihre Software ausliefern. WP Updates Notifier habe ich 2011 zum ersten Mal auf WordPress.org veröffentlicht, und heute läuft es auf rund 30.000 Websites.','Scott Cariss on GitHub'=>'Scott Cariss auf GitHub','Scott Cariss on LinkedIn'=>'Scott Cariss auf LinkedIn','For power users'=>'Für Power-User','You can hide this tab with a line in wp-config.php:'=>'Du kannst diesen Tab mit einer Zeile in der wp-config.php ausblenden:','The setting is never stored and has no field on the settings screen. An environment variable, a configuration source or the sc_wpun_config_value filter can set it too. If you hide the tab, please consider a donation or a review in return.'=>'Die Einstellung wird nie gespeichert und hat kein Feld auf der Einstellungsseite. Sie kann auch über eine Umgebungsvariable, eine Konfigurationsquelle oder den Filter sc_wpun_config_value gesetzt werden. Wenn du den Tab ausblendest, denk bitte im Gegenzug über eine Spende oder eine Bewertung nach.','No channel modules are available.'=>'Es sind keine Kanal-Module verfügbar.','Choose where the update notifications are to be sent.'=>'Wähle aus, wohin die Benachrichtigungen über Aktualisierungen gesendet werden sollen.','Cancel'=>'Abbrechen','Add channel'=>'Kanal hinzufügen','Add %s channel'=>'%s-Kanal hinzufügen','Edit %s'=>'%s bearbeiten','There is no such channel module.'=>'Dieses Kanal-Modul gibt es nicht.','There is no such channel.'=>'Diesen Kanal gibt es nicht.','%s is defined in code and cannot be changed here.'=>'%s ist im Code definiert und kann hier nicht geändert werden.','Save channel'=>'Kanal speichern','There is a problem'=>'Es gibt ein Problem','The channel was not saved. Please correct the following.'=>'Der Kanal wurde nicht gespeichert. Bitte korrigiere Folgendes.','Set by %s'=>'Festgelegt durch %s','Channel'=>'Kanal','ID'=>'ID','The id is made from the label when the channel is saved and cannot be changed afterwards.'=>'Die ID wird beim Speichern des Kanals aus der Bezeichnung erzeugt und kann danach nicht mehr geändert werden.','Constants for this channel start with %s'=>'Konstanten für diesen Kanal beginnen mit %s','Updates already waiting'=>'Bereits ausstehende Aktualisierungen','Don\'t send the updates that are already waiting'=>'Bereits ausstehende Aktualisierungen nicht senden','Only updates that appear after the channel is switched on are sent. Applies when the channel is saved switched on.'=>'Es werden nur Aktualisierungen gesendet, die nach dem Einschalten des Kanals erscheinen. Gilt, wenn der Kanal eingeschaltet gespeichert wird.','Routing'=>'Routing','On the General tab, plugins are not checked.'=>'Im Tab „Allgemein“ ist festgelegt, dass Plugins nicht geprüft werden.','On the General tab, only active plugins are checked, so "All" here acts like "Only active ones" for plugins.'=>'Im Tab „Allgemein“ ist festgelegt, dass nur aktive Plugins geprüft werden, daher wirkt „Alle“ hier für Plugins wie „Nur aktive“.','On the General tab, themes are not checked.'=>'Im Tab „Allgemein“ ist festgelegt, dass Themes nicht geprüft werden.','On the General tab, only active themes are checked, so "All" here acts like "Only active ones" for themes.'=>'Im Tab „Allgemein“ ist festgelegt, dass nur aktive Themes geprüft werden, daher wirkt „Alle“ hier für Themes wie „Nur aktive“.','On the General tab, WordPress updates are not checked.'=>'Im Tab „Allgemein“ ist festgelegt, dass WordPress-Aktualisierungen nicht geprüft werden.','On the General tab, only major releases are checked.'=>'Im Tab „Allgemein“ ist festgelegt, dass nur Hauptversionen geprüft werden.','Settings'=>'Einstellungen','Label'=>'Bezeichnung','The settings are not valid.'=>'Die Einstellungen sind ungültig.','%s added.'=>'%s hinzugefügt.','%s saved.'=>'%s gespeichert.','You are not allowed to do that.'=>'Dazu bist du nicht berechtigt.','Delete %s?'=>'%s löschen?','Channels'=>'Kanäle','No channels are set up yet. A channel is where the update notifications are sent, for example an email address.'=>'Es sind noch keine Kanäle eingerichtet. Ein Kanal ist das Ziel, an das die Benachrichtigungen über Aktualisierungen gesendet werden, zum Beispiel eine E-Mail-Adresse.','Module'=>'Modul','Last delivery'=>'Letzte Zustellung','Unavailable channels'=>'Nicht verfügbare Kanäle','These channels belong to modules that need a newer version of WP Updates Notifier. Nothing is sent through them and their settings are kept.'=>'Diese Kanäle gehören zu Modulen, die eine neuere Version von WP Updates Notifier benötigen. Über sie wird nichts gesendet, und ihre Einstellungen bleiben erhalten.','Status'=>'Status','Unavailable: %s'=>'Nicht verfügbar: %s','Defined in code'=>'Im Code definiert','Show more details'=>'Weitere Details anzeigen','On'=>'An','Off'=>'Aus','Edit'=>'Bearbeiten','Send test to %s'=>'Test an %s senden','Send test'=>'Test senden','Duplicate %s'=>'%s duplizieren','Duplicate'=>'Duplizieren','Disable %s'=>'%s deaktivieren','Disable'=>'Deaktivieren','Enable %s'=>'%s aktivieren','Enable'=>'Aktivieren','Delete %s'=>'%s löschen','Delete'=>'Löschen','Delete the channel %s? Its settings and delivery history are removed. This cannot be undone.'=>'Den Kanal %s löschen? Seine Einstellungen und sein Zustellverlauf werden entfernt. Dies kann nicht rückgängig gemacht werden.','No known item types'=>'Keine bekannten Elementtypen','All updates'=>'Alle Aktualisierungen','Never'=>'Nie','Sent %s'=>'Gesendet: %s','Failed %1$s: %2$s'=>'Fehlgeschlagen (%1$s): %2$s','Rate limited, next try after %s'=>'Rate-Limit erreicht, nächster Versuch nach %s','%s cannot send a test message.'=>'%s kann keine Testnachricht senden.','Test message sent through %s.'=>'Testnachricht über %s gesendet.','The test message could not be sent through %1$s: %2$s'=>'Die Testnachricht konnte nicht über %1$s gesendet werden: %2$s','%1$s cannot be switched here: set by %2$s.'=>'%1$s kann hier nicht umgeschaltet werden: festgelegt durch %2$s.','%s enabled.'=>'%s aktiviert.','%s disabled.'=>'%s deaktiviert.','%s (copy)'=>'%s (Kopie)','Channel duplicated as %s.'=>'Kanal als %s dupliziert.','%s deleted.'=>'%s gelöscht.','Check for updates and notify now'=>'Jetzt nach Aktualisierungen suchen und benachrichtigen','Only updates that were not notified yet are sent. To try a channel, send a test message from the %s.'=>'Es werden nur Aktualisierungen gesendet, über die noch nicht benachrichtigt wurde. Um einen Kanal auszuprobieren, sende eine Testnachricht im %s.','Channels tab'=>'Tab „Kanäle“','Checked just now. Nothing was sent because no channel is enabled.'=>'Gerade geprüft. Es wurde nichts gesendet, da kein Kanal aktiviert ist.','Checked just now. Nothing new to send.'=>'Gerade geprüft. Es gibt nichts Neues zu senden.','Checked just now. Sent to %d channel.'=>'Gerade geprüft. An %d Kanal gesendet.' . "\0" . 'Gerade geprüft. An %d Kanäle gesendet.','Checked just now. %1$d channel failed: %2$s'=>'Gerade geprüft. %1$d Kanal fehlgeschlagen: %2$s' . "\0" . 'Gerade geprüft. %1$d Kanäle fehlgeschlagen: %2$s','Checked just now. Sent to %1$d channel; %2$d failed: %3$s'=>'Gerade geprüft. An %1$d Kanal gesendet; %2$d fehlgeschlagen: %3$s' . "\0" . 'Gerade geprüft. An %1$d Kanäle gesendet; %2$d fehlgeschlagen: %3$s','Error:'=>'Fehler:','Clear the saved value'=>'Gespeicherten Wert löschen','Clear the saved value of %s'=>'Gespeicherten Wert von %s löschen','A value is saved. Leave this empty to keep it, or type a new value to replace it.'=>'Es ist ein Wert gespeichert. Lass das Feld leer, um ihn zu behalten, oder gib einen neuen Wert ein, um ihn zu ersetzen.','(required)'=>'(erforderlich)','That plugin or theme is not installed.'=>'Dieses Plugin oder Theme ist nicht installiert.','No update is waiting for %s, so there is no version to skip.'=>'Für %s wartet keine Aktualisierung, also gibt es keine Version zum Überspringen.','A newer version of %s is waiting than the one on the page. Reload the page and try again.'=>'Für %s wartet eine neuere Version als die auf der Seite angezeigte. Lade die Seite neu und versuche es erneut.','Update notifications for %s are muted.'=>'Die Benachrichtigungen über Aktualisierungen für %s sind stummgeschaltet.','Update notifications for %1$s version %2$s are skipped.'=>'Die Benachrichtigungen über Aktualisierungen für %1$s Version %2$s werden übersprungen.','Update notifications for %s are on again.'=>'Die Benachrichtigungen über Aktualisierungen für %s sind wieder eingeschaltet.','Muted'=>'Stummgeschaltet','A muted plugin or theme is left out of the update notifications. WordPress\'s own update notices, emails and automatic updates are not affected.'=>'Ein stummgeschaltetes Plugin oder Theme wird in den Benachrichtigungen über Aktualisierungen weggelassen. Die eigenen Hinweise, E-Mails und automatischen Aktualisierungen von WordPress sind davon nicht betroffen.','Nothing is muted. Muting a plugin or theme stops the update notifications about it, always or for the version that is waiting. Mute a plugin from the %s, or a plugin or theme with the form below.'=>'Nichts ist stummgeschaltet. Wenn du ein Plugin oder Theme stummschaltest, bekommst du keine Benachrichtigungen mehr über seine Aktualisierungen, dauerhaft oder für die wartende Version. Schalte ein Plugin im %s stumm oder ein Plugin oder Theme mit dem Formular unten.','Plugins screen'=>'Plugin-Bildschirm','Muted plugins and themes'=>'Stummgeschaltete Plugins und Themes','Name'=>'Name','Mute'=>'Stummschaltung','Muted by'=>'Stummgeschaltet von','Unmute'=>'Stummschaltung aufheben','Plugin'=>'Plugin','Theme'=>'Theme','Set in code'=>'Im Code festgelegt','Unknown user'=>'Unbekannter Benutzer','%1$s, %2$s'=>'%1$s, %2$s','%s, not installed'=>'%s, nicht installiert','Always'=>'Immer','Version %s'=>'Version %s','No update waiting'=>'Keine Aktualisierung wartet','Update to %s waiting'=>'Aktualisierung auf %s wartet','Set in code, it cannot be unmuted here'=>'Im Code festgelegt, kann hier nicht aufgehoben werden','You may not unmute'=>'Du darfst die Stummschaltung nicht aufheben','Unmute %s'=>'Stummschaltung für %s aufheben','Mute a plugin or theme'=>'Plugin oder Theme stummschalten','Every installed plugin and theme is muted.'=>'Jedes installierte Plugin und Theme ist stummgeschaltet.','Plugin or theme'=>'Plugin oder Theme','Plugins'=>'Plugins','Themes'=>'Themes','What to mute'=>'Was stummgeschaltet werden soll','Skip the waiting version'=>'Wartende Version überspringen','Notifications start again when a newer version than the waiting one is offered. It needs an update to be waiting.'=>'Die Benachrichtigungen beginnen wieder, sobald eine neuere Version als die wartende angeboten wird. Dafür muss eine Aktualisierung warten.','Choose a plugin or theme to mute.'=>'Wähle ein Plugin oder Theme zum Stummschalten aus.','WP Updates Notifier now runs for the whole network, and only when it is network-activated. Until it is, it sends no notifications for this site or any other.'=>'WP Updates Notifier läuft jetzt für das ganze Netzwerk und nur, wenn es netzwerkweit aktiviert ist. Bis dahin sendet es keine Benachrichtigungen, weder für diese Website noch für eine andere.','WP Updates Notifier is not network-activated'=>'WP Updates Notifier ist nicht netzwerkweit aktiviert','Go to the network plugins'=>'Zu den Plugins des Netzwerks','Updates Notifier'=>'Updates Notifier','This add-on\'s WP Updates Notifier API requirement (%s) could not be read.'=>'Die Anforderung dieses Add-ons an die API von WP Updates Notifier (%s) konnte nicht gelesen werden.','This add-on needs the WP Updates Notifier API %1$s. This site has %2$s. Update WP Updates Notifier.'=>'Dieses Add-on benötigt die API %1$s von WP Updates Notifier. Diese Website hat %2$s. Aktualisiere WP Updates Notifier.','Mute update notifications for %s'=>'Benachrichtigungen über Aktualisierungen für %s stummschalten','Mute update notifications'=>'Update-Benachrichtigungen stummschalten','Unmute update notifications for %s'=>'Stummschaltung der Benachrichtigungen über Aktualisierungen für %s aufheben','Unmute update notifications'=>'Stummschaltung der Update-Benachrichtigungen aufheben','Undo'=>'Rückgängig','Undo skipping the version'=>'Überspringen der Version rückgängig machen','Update notifications muted'=>'Update-Benachrichtigungen stummgeschaltet','Notifications for version %s are skipped'=>'Benachrichtigungen für Version %s werden übersprungen','%s (set in code)'=>'%s (im Code festgelegt)','Don\'t notify me about version %s'=>'Über Version %s nicht benachrichtigen','Notifications for version %s are skipped.'=>'Benachrichtigungen für Version %s werden übersprungen.','Update notifications muted for %d plugin.'=>'Update-Benachrichtigungen für %d Plugin stummgeschaltet.' . "\0" . 'Update-Benachrichtigungen für %d Plugins stummgeschaltet.','Update notifications are on again for %d plugin.'=>'Update-Benachrichtigungen sind für %d Plugin wieder eingeschaltet.' . "\0" . 'Update-Benachrichtigungen sind für %d Plugins wieder eingeschaltet.','Sorry, you are not allowed to access this page.'=>'Du hast leider keine Berechtigung, auf diese Seite zuzugreifen.','%1$s &lsaquo; %2$s'=>'%1$s &lsaquo; %2$s','Error: %s'=>'Fehler: %s','General'=>'Allgemein','About'=>'Über','Settings sections'=>'Einstellungsbereiche','Last checked: never'=>'Zuletzt geprüft: nie','Last checked: %s'=>'Zuletzt geprüft: %s','Next check: not scheduled. Save the settings to schedule it.'=>'Nächste Prüfung: nicht geplant. Speichere die Einstellungen, um sie zu planen.','Next check: %s'=>'Nächste Prüfung: %s','Save settings'=>'Einstellungen speichern','%1$s at %2$s'=>'%1$s um %2$s','Choose how often to check for updates.'=>'Wähle aus, wie oft nach Aktualisierungen gesucht werden soll.','Choose whether to be told about WordPress updates.'=>'Wähle aus, ob du über WordPress-Aktualisierungen informiert werden möchtest.','Choose whether to be told about plugin updates.'=>'Wähle aus, ob du über Plugin-Aktualisierungen informiert werden möchtest.','Choose whether to be told about theme updates.'=>'Wähle aus, ob du über Theme-Aktualisierungen informiert werden möchtest.','Choose whether to hide the update notices.'=>'Wähle aus, ob die Aktualisierungshinweise ausgeblendet werden sollen.','Choose a value for %s.'=>'Wähle einen Wert für %s.','This is a test message from WP Updates Notifier.'=>'Dies ist eine Testnachricht von WP Updates Notifier.','%s (no longer available)'=>'%s (nicht mehr verfügbar)','The saved frequency is no longer available on this site, so checks run at the interval they were last scheduled with. Choose a frequency and save to change it.'=>'Die gespeicherte Häufigkeit ist auf dieser Website nicht mehr verfügbar, daher laufen die Prüfungen in dem Intervall, mit dem sie zuletzt geplant wurden. Wähle eine Häufigkeit und speichere, um das zu ändern.','Scheduled checks run WordPress\'s automatic updates first, so updates it installs by itself are not reported.'=>'Geplante Prüfungen führen zuerst die automatischen Aktualisierungen von WordPress aus, daher werden Aktualisierungen, die WordPress selbst installiert, nicht gemeldet.','The display "%1$s" cannot show an on or off value, so "%2$s" is used.'=>'Die Darstellung „%1$s“ kann keinen An/Aus-Wert anzeigen, daher wird „%2$s“ verwendet.','Yes'=>'Ja','No'=>'Nein','A channel type may only contain lower case letters, digits and underscores.'=>'Ein Kanaltyp darf nur Kleinbuchstaben, Ziffern und Unterstriche enthalten.','A channel of type "%s" is already registered.'=>'Ein Kanal vom Typ „%s“ ist bereits registriert.','Needs WP Updates Notifier API %1$s; this site has %2$s. Update WP Updates Notifier.'=>'Benötigt die API %1$s von WP Updates Notifier; diese Website hat %2$s. Aktualisiere WP Updates Notifier.','Its API requirement "%s" could not be read.'=>'Seine API-Anforderung „%s“ konnte nicht gelesen werden.','An instance defined in code cannot be saved.'=>'Eine im Code definierte Instanz kann nicht gespeichert werden.','An instance defined in code cannot be deleted.'=>'Eine im Code definierte Instanz kann nicht gelöscht werden.','The field "%2$s" of the "%1$s" channel cannot be supplied from outside the database: the name "enabled" is reserved, and names may only contain a-z, 0-9 and single underscores.'=>'Das Feld „%2$s“ des Kanals „%1$s“ kann nicht von außerhalb der Datenbank bereitgestellt werden: Der Name „enabled“ ist reserviert, und Namen dürfen nur a-z, 0-9 und einzelne Unterstriche enthalten.','The value is not valid for this channel.'=>'Der Wert ist für diesen Kanal ungültig.','The value could not be checked: %s was thrown.'=>'Der Wert konnte nicht geprüft werden: %s wurde ausgelöst.','constant SC_WPUN_CHANNELS'=>'die Konstante SC_WPUN_CHANNELS','The constant must be a JSON string.'=>'Die Konstante muss ein JSON-String sein.','The value must be a JSON string.'=>'Der Wert muss ein JSON-String sein.','The JSON must be a list of channels.'=>'Das JSON muss eine Liste von Kanälen sein.','the sc_wpun_channels filter'=>'den Filter sc_wpun_channels','Channel %d repeats the id of an earlier channel and was skipped.'=>'Kanal %d wiederholt die ID eines früheren Kanals und wurde übersprungen.','Channel %d is not valid and was skipped.'=>'Kanal %d ist ungültig und wurde übersprungen.','Some configuration values supplied from outside the database are not valid. Invalid settings fall back to the saved value; a channel with an invalid value does not send until it is fixed.'=>'Einige Konfigurationswerte, die von außerhalb der Datenbank kommen, sind ungültig. Für ungültige Einstellungen wird der gespeicherte Wert verwendet; ein Kanal mit einem ungültigen Wert sendet nichts, bis der Wert korrigiert ist.','WP Updates Notifier cannot use some configuration values'=>'WP Updates Notifier kann einige Konfigurationswerte nicht verwenden','Some values supplied by constants, environment variables or other sources are not valid. Invalid settings fall back to the saved value; a channel with an invalid value does not send until it is fixed.'=>'Einige Werte aus Konstanten, Umgebungsvariablen oder anderen Quellen sind ungültig. Für ungültige Einstellungen wird der gespeicherte Wert verwendet; ein Kanal mit einem ungültigen Wert sendet nichts, bis der Wert korrigiert ist.','Review the notification settings'=>'Benachrichtigungseinstellungen überprüfen','the sc_wpun_config_value filter'=>'den Filter sc_wpun_config_value','The value is not valid for this setting, so the default is used.'=>'Der Wert ist für diese Einstellung ungültig, daher wird der Standardwert verwendet.','The value is not valid for this setting, so the saved one is used.'=>'Der Wert ist für diese Einstellung ungültig, daher wird der gespeicherte Wert verwendet.','The value is not valid for this field.'=>'Der Wert ist für dieses Feld ungültig.','The value is not a recognised on or off value (1, true, yes, on, 0, false, no, off), so environment variables are not read.'=>'Der Wert ist kein gültiger An/Aus-Wert (1, true, yes, on, 0, false, no, off), daher werden Umgebungsvariablen nicht gelesen.','Every entry must implement WPUN\\Config_Source.'=>'Jeder Eintrag muss WPUN\\Config_Source implementieren.','a configuration source'=>'eine Konfigurationsquelle','constant %s'=>'die Konstante %s','This channel cannot send a test message.'=>'Dieser Kanal kann keine Testnachricht senden.','This channel is switched off.'=>'Dieser Kanal ist ausgeschaltet.','The "%s" channel did not return a Delivery_Result.'=>'Der Kanal „%s“ hat kein Delivery_Result zurückgegeben.','The "%s" channel failed with an error.'=>'Der Kanal „%s“ ist mit einem Fehler fehlgeschlagen.','The channel is misconfigured: %s is not valid.'=>'Der Kanal ist falsch konfiguriert: %s ist ungültig.','The "%1$s" channel is not available: %2$s'=>'Der Kanal „%1$s“ ist nicht verfügbar: %2$s','The "%s" channel is not available.'=>'Der Kanal „%s“ ist nicht verfügbar.','The display "%1$s" cannot show several choices, so "%2$s" is used.'=>'Die Darstellung „%1$s“ kann keine Mehrfachauswahl anzeigen, daher wird „%2$s“ verwendet.','The display "%1$s" cannot show a single choice, so "%2$s" is used.'=>'Die Darstellung „%1$s“ kann keine Einzelauswahl anzeigen, daher wird „%2$s“ verwendet.','environment variable %s'=>'die Umgebungsvariable %s','The field type "%s" must be an array with a callable "render" and a callable "sanitize", so it is ignored.'=>'Der Feldtyp „%s“ muss ein Array mit einem aufrufbaren „render“ und einem aufrufbaren „sanitize“ sein, daher wird er ignoriert.','No field type "%s" is registered, so the field is ignored. Register it with the sc_wpun_field_types filter.'=>'Es ist kein Feldtyp „%s“ registriert, daher wird das Feld ignoriert. Registriere ihn mit dem Filter sc_wpun_field_types.','Enter a full web address that starts with http:// or https://.'=>'Gib eine vollständige Webadresse ein, die mit http:// oder https:// beginnt.','One or more email addresses are not valid.'=>'Eine oder mehrere E-Mail-Adressen sind ungültig.','Enter a whole number.'=>'Gib eine ganze Zahl ein.','Enter a number that is at least %d.'=>'Gib eine Zahl ein, die mindestens %d ist.','Enter a number that is at most %d.'=>'Gib eine Zahl ein, die höchstens %d ist.','The choice for "%s" is not valid.'=>'Die Auswahl für „%s“ ist ungültig.','%s is required.'=>'%s ist erforderlich.','The value for "%s" is not valid.'=>'Der Wert für „%s“ ist ungültig.','WordPress'=>'WordPress','The mute was refused.'=>'Die Stummschaltung wurde abgelehnt.','The mute was refused: it is for another item.'=>'Die Stummschaltung wurde abgelehnt: Sie gilt für ein anderes Element.','That item is not muted.'=>'Dieses Element ist nicht stummgeschaltet.','That mute is set in code and cannot be removed here.'=>'Diese Stummschaltung ist im Code festgelegt und kann hier nicht entfernt werden.','Removing the mute was refused.'=>'Das Aufheben der Stummschaltung wurde abgelehnt.','WordPress core cannot be muted. Use the core notification setting instead.'=>'WordPress selbst kann nicht stummgeschaltet werden. Nutze stattdessen die Einstellung für Core-Benachrichtigungen.','That kind of item cannot be muted.'=>'Diese Art von Element kann nicht stummgeschaltet werden.','Say which item to mute.'=>'Gib an, welches Element stummgeschaltet werden soll.','The version to skip cannot be empty.'=>'Die zu überspringende Version darf nicht leer sein.','That mute is set in code and cannot be changed here.'=>'Diese Stummschaltung ist im Code festgelegt und kann hier nicht geändert werden.','…and %d more'=>'…und %d weitere' . "\0" . '…und %d weitere','Reminder: these updates are still waiting for %1$s (%2$s)'=>'Erinnerung: Diese Aktualisierungen stehen für %1$s (%2$s) noch aus','There are updates available for %1$s (%2$s)'=>'Für %1$s (%2$s) sind Aktualisierungen verfügbar','%1$s from version %2$s to %3$s'=>'%1$s von Version %2$s auf %3$s','Please visit %s to update.'=>'Besuche bitte %s, um zu aktualisieren.','Go to the Updates screen to update.'=>'Gehe zur Seite „Aktualisierungen“, um zu aktualisieren.','Details'=>'Details','Changelog'=>'Änderungsprotokoll','%s details'=>'Details zu %s','%s changelog'=>'Änderungsprotokoll von %s','WP Updates Notifier: updates available for %s'=>'WP Updates Notifier: Aktualisierungen für %s verfügbar','Some notification modules need a newer version of WP Updates Notifier and are switched off. Their settings have been kept.'=>'Einige Benachrichtigungsmodule benötigen eine neuere Version von WP Updates Notifier und sind ausgeschaltet. Ihre Einstellungen bleiben erhalten.','Some WP Updates Notifier modules need a newer version'=>'Einige Module von WP Updates Notifier benötigen eine neuere Version','Some notification modules need a newer version of WP Updates Notifier than this site has, so they are switched off. Their settings have been kept.'=>'Einige Benachrichtigungsmodule benötigen eine neuere Version von WP Updates Notifier, als diese Website hat, daher sind sie ausgeschaltet. Ihre Einstellungen bleiben erhalten.','Update WP Updates Notifier'=>'WP Updates Notifier aktualisieren','Item types'=>'Elementtypen','Leave every box unticked to receive all types, including ones added later.'=>'Lass alle Kästchen leer, um alle Typen zu erhalten, auch später hinzugefügte.','Plugins and themes'=>'Plugins und Themes','Applies after the plugin and theme settings on the General tab.'=>'Wird nach den Plugin- und Theme-Einstellungen im Tab „Allgemein“ angewendet.','All'=>'Alle','Only active ones'=>'Nur aktive','WordPress updates'=>'WordPress-Aktualisierungen','Applies after the WordPress updates setting on the General tab.'=>'Wird nach der Einstellung für WordPress-Aktualisierungen im Tab „Allgemein“ angewendet.','Only major releases'=>'Nur Hauptversionen','Reminders'=>'Erinnerungen','Repeat every update that is still waiting, in one message, until it is installed. New updates are still sent at once.'=>'Alle noch ausstehenden Aktualisierungen in einer gemeinsamen Nachricht wiederholen, bis sie installiert sind. Neue Aktualisierungen werden weiterhin sofort gesendet.','Daily'=>'Täglich','Weekly'=>'Wöchentlich','Frequency to check'=>'Prüfhäufigkeit','Update notice'=>'Aktualisierungshinweis','Hide the WordPress update notice from users who cannot update WordPress'=>'Den WordPress-Aktualisierungshinweis für Benutzer ausblenden, die WordPress nicht aktualisieren können','About tab'=>'Tab „Über“','Notify about WordPress updates?'=>'Über WordPress-Aktualisierungen benachrichtigen?','Yes, but only major releases'=>'Ja, aber nur Hauptversionen','Notify about plugin updates?'=>'Über Plugin-Aktualisierungen benachrichtigen?','Notify about theme updates?'=>'Über Theme-Aktualisierungen benachrichtigen?','Yes, but only active plugins'=>'Ja, aber nur aktive Plugins','Yes, but only active themes'=>'Ja, aber nur aktive Themes','WP Updates Notifier checks for updates'=>'WP Updates Notifier prüft auf Aktualisierungen','WP-Cron is switched off for WP Updates Notifier'=>'WP-Cron ist für WP Updates Notifier ausgeschaltet','WP Updates Notifier has a channel to send through'=>'WP Updates Notifier hat einen Kanal zum Senden','The modules of the WP Updates Notifier channels are available'=>'Die Module der Kanäle von WP Updates Notifier sind verfügbar','The last notification of each WP Updates Notifier channel was delivered'=>'Die letzte Benachrichtigung jedes Kanals von WP Updates Notifier wurde zugestellt','The update check is not scheduled, so no update will be reported.'=>'Die Aktualisierungsprüfung ist nicht geplant, daher wird keine Aktualisierung gemeldet.','The update checks are not running. The next one is long overdue and none ran lately. WP-Cron may not be running on this site.'=>'Die Aktualisierungsprüfungen laufen nicht. Die nächste ist längst überfällig, und in letzter Zeit wurde keine ausgeführt. WP-Cron läuft auf dieser Website möglicherweise nicht.','The update check is scheduled and running.'=>'Die Aktualisierungsprüfung ist geplant und läuft.','WP Updates Notifier is not checking for updates'=>'WP Updates Notifier prüft nicht auf Aktualisierungen','WP Updates Notifier checks run from a server cron'=>'Die Prüfungen von WP Updates Notifier laufen über einen Server-Cron','WP-Cron is switched off, and the update checks are running from a server cron.'=>'WP-Cron ist ausgeschaltet, und die Aktualisierungsprüfungen laufen über einen Server-Cron.','WP-Cron is switched off, so WP Updates Notifier may not check'=>'WP-Cron ist ausgeschaltet, daher prüft WP Updates Notifier möglicherweise nicht','DISABLE_WP_CRON is set and no update check ran lately. Make a server cron request wp-cron.php regularly, or run "wp updates-notifier check" from a server cron.'=>'DISABLE_WP_CRON ist gesetzt, und in letzter Zeit wurde keine Aktualisierungsprüfung ausgeführt. Lass einen Server-Cron regelmäßig wp-cron.php aufrufen oder führe "wp updates-notifier check" über einen Server-Cron aus.','At least one channel is switched on and can send.'=>'Mindestens ein Kanal ist eingeschaltet und kann senden.','WP Updates Notifier has no channel to send through'=>'WP Updates Notifier hat keinen Kanal zum Senden','No channel is switched on and able to send, so nothing will be sent. Switch a channel on if you want to be told about updates.'=>'Es ist kein Kanal eingeschaltet, der senden kann, daher wird nichts gesendet. Schalte einen Kanal ein, wenn du über Aktualisierungen informiert werden möchtest.','Every channel that is switched on has its module.'=>'Jeder eingeschaltete Kanal hat sein Modul.','Some WP Updates Notifier channels cannot send'=>'Einige Kanäle von WP Updates Notifier können nicht senden','These channels are switched on, but their module is not available, so nothing is sent through them. Activate the add-on that provides the module, or switch the channel off.'=>'Diese Kanäle sind eingeschaltet, aber ihr Modul ist nicht verfügbar, daher wird nichts über sie gesendet. Aktiviere das Add-on, das das Modul bereitstellt, oder schalte den Kanal aus.','No channel that is switched on failed its last delivery.'=>'Bei keinem eingeschalteten Kanal ist die letzte Zustellung fehlgeschlagen.','Some WP Updates Notifier channels failed to deliver'=>'Einige Kanäle von WP Updates Notifier konnten nicht zustellen','The last delivery of these channels failed. The update will be tried again at the next check.'=>'Die letzte Zustellung über diese Kanäle ist fehlgeschlagen. Die Aktualisierung wird bei der nächsten Prüfung erneut versucht.','Check frequency'=>'Prüfhäufigkeit','Next check'=>'Nächste Prüfung','Last check'=>'Letzte Prüfung','WP-Cron switched off (DISABLE_WP_CRON)'=>'WP-Cron ausgeschaltet (DISABLE_WP_CRON)','set in code'=>'im Code festgelegt','None'=>'Keine','Disabled by DISALLOW_FILE_MODS'=>'Deaktiviert durch DISALLOW_FILE_MODS','Disabled by AUTOMATIC_UPDATER_DISABLED or the automatic_updater_disabled filter'=>'Deaktiviert durch AUTOMATIC_UPDATER_DISABLED oder den Filter automatic_updater_disabled','Version control checkout'=>'Checkout einer Versionsverwaltung','Can run'=>'Können laufen','WordPress automatic updates'=>'Automatische Aktualisierungen von WordPress','Configuration problem'=>'Konfigurationsproblem','Availability'=>'Verfügbarkeit','Next try after'=>'Nächster Versuch frühestens','Frequency: %s'=>'Häufigkeit: %s','Last check: %s'=>'Letzte Prüfung: %s','Email notifications continue as before.'=>'E-Mail-Benachrichtigungen funktionieren weiter wie bisher.','Email notifications are switched off, so this site currently sends no update notifications. You can turn them on at %s'=>'E-Mail-Benachrichtigungen sind ausgeschaltet, daher sendet diese Website derzeit keine Benachrichtigungen über Aktualisierungen. Du kannst sie hier einschalten: %s','Slack notifications are not supported in this version of WP Updates Notifier. Your Slack settings have been kept.'=>'Slack-Benachrichtigungen werden in dieser Version von WP Updates Notifier nicht unterstützt. Deine Slack-Einstellungen bleiben erhalten.','New notification channels and features are coming in future releases.'=>'Neue Benachrichtigungskanäle und Funktionen folgen in kommenden Versionen.','WP Updates Notifier: Slack notifications are no longer supported'=>'WP Updates Notifier: Slack-Benachrichtigungen werden nicht mehr unterstützt','Slack notifications are no longer supported'=>'Slack-Benachrichtigungen werden nicht mehr unterstützt','Dismiss this notice'=>'Diesen Hinweis ausblenden','Slack notifications are no longer supported by WP Updates Notifier'=>'Slack-Benachrichtigungen werden von WP Updates Notifier nicht mehr unterstützt','Slack notifications are not supported in this version of WP Updates Notifier, so none are sent. Your Slack settings have been kept.'=>'Slack-Benachrichtigungen werden in dieser Version von WP Updates Notifier nicht unterstützt, daher werden keine gesendet. Deine Slack-Einstellungen bleiben erhalten.','always'=>'immer','version %s'=>'Version %s','not scheduled'=>'nicht geplant','never'=>'nie','rejected: %s'=>'abgelehnt: %s','unknown module'=>'unbekanntes Modul','success'=>'Erfolg','failure'=>'Fehler','not set'=>'nicht gesetzt','set'=>'gesetzt','The filter must return a WPUN\\Notification.'=>'Der Filter muss eine WPUN\\Notification zurückgeben.','Automatic updates are on, but WordPress has not installed this update yet.'=>'Automatische Aktualisierungen sind aktiviert, aber WordPress hat diese Aktualisierung noch nicht installiert.','Compatibility with WordPress %s: unknown'=>'Kompatibilität mit WordPress %s: unbekannt','Compatibility with WordPress %s: tested by its author'=>'Kompatibilität mit WordPress %s: vom Autor getestet','Compatibility with WordPress %1$s: not tested yet (tested up to %2$s)'=>'Kompatibilität mit WordPress %1$s: noch nicht getestet (getestet bis %2$s)','Warning: this version needs PHP %1$s; the site runs PHP %2$s.'=>'Warnung: Diese Version benötigt PHP %1$s; auf der Website läuft PHP %2$s.','Warning: this version needs WordPress %1$s; the site runs WordPress %2$s.'=>'Warnung: Diese Version benötigt WordPress %1$s; auf der Website läuft WordPress %2$s.','The version "%s" could not be read. Use one to three numbers, such as "1.2.0".'=>'Die Version „%s“ konnte nicht gelesen werden. Verwende eine bis drei Zahlen, zum Beispiel „1.2.0“.','The version constraint "%s" could not be read. Use Composer syntax, such as "^1.0" or ">=1.0 <2.0".'=>'Die Versionsbedingung „%s“ konnte nicht gelesen werden. Verwende die Composer-Syntax, zum Beispiel „^1.0“ oder „>=1.0 <2.0“.','No channel instance is switched on and available, so there is nobody to notify.'=>'Keine Kanalinstanz ist eingeschaltet und verfügbar, daher gibt es niemanden zu benachrichtigen.','%d channel instance failed.'=>'%d Kanalinstanz ist fehlgeschlagen.' . "\0" . '%d Kanalinstanzen sind fehlgeschlagen.','Dry run finished, nothing was sent or changed. %d channel instance would be sent a message.'=>'Testlauf beendet, es wurde nichts gesendet oder geändert. An %d Kanalinstanz würde eine Nachricht gesendet.' . "\0" . 'Testlauf beendet, es wurde nichts gesendet oder geändert. An %d Kanalinstanzen würde eine Nachricht gesendet.','Check finished. %d channel instance was sent a message.'=>'Prüfung beendet. An %d Kanalinstanz wurde eine Nachricht gesendet.' . "\0" . 'Prüfung beendet. An %d Kanalinstanzen wurde eine Nachricht gesendet.','There is no channel instance "%s".'=>'Es gibt keine Kanalinstanz „%s“.','test message sent'=>'Testnachricht gesendet','No channel instance is switched on, available and able to send a test message.'=>'Keine Kanalinstanz ist eingeschaltet, verfügbar und in der Lage, eine Testnachricht zu senden.','%d test message could not be sent.'=>'%d Testnachricht konnte nicht gesendet werden.' . "\0" . '%d Testnachrichten konnten nicht gesendet werden.','%d test message sent.'=>'%d Testnachricht gesendet.' . "\0" . '%d Testnachrichten gesendet.','Schedule'=>'Zeitplan','Settings of %s'=>'Einstellungen von %s','Pending updates'=>'Ausstehende Updates','%1$s (%2$s)'=>'%1$s (%2$s)','%s is already muted that way.'=>'%s ist bereits auf diese Weise stummgeschaltet.','%s is not muted.'=>'%s ist nicht stummgeschaltet.','Say whether the names are plugins or themes, then one or more names.'=>'Gib an, ob die Namen Plugins oder Themes sind, und dann einen oder mehrere Namen.','The plugin "%s" is not installed.'=>'Das Plugin „%s“ ist nicht installiert.','The theme "%s" is not installed.'=>'Das Theme „%s“ ist nicht installiert.','%1$d of %2$d could not be changed.'=>'%1$d von %2$d konnten nicht geändert werden.','%1$s cannot be used: %2$s.'=>'%1$s kann nicht verwendet werden: %2$s.','%s is switched off.'=>'%s ist ausgeschaltet.','switched off'=>'ausgeschaltet','waiting until %s'=>'wartet bis %s','recorded without sending'=>'ohne Senden vermerkt','would send a reminder with %d item'=>'würde eine Erinnerung mit %d Eintrag senden' . "\0" . 'würde eine Erinnerung mit %d Einträgen senden','sent a reminder with %d item'=>'Erinnerung mit %d Eintrag gesendet' . "\0" . 'Erinnerung mit %d Einträgen gesendet','would send %d item'=>'würde %d Eintrag senden' . "\0" . 'würde %d Einträge senden','sent %d item'=>'%d Eintrag gesendet' . "\0" . '%d Einträge gesendet','failed: %s'=>'fehlgeschlagen: %s','the routing failed'=>'die Weiterleitung ist fehlgeschlagen','nothing new'=>'nichts Neues','Email'=>'E-Mail','Sends the notification to one or more email addresses.'=>'Sendet die Benachrichtigung an eine oder mehrere E-Mail-Adressen.','Send to'=>'Senden an','Separate multiple email addresses with a comma (,).'=>'Trenne mehrere E-Mail-Adressen mit einem Komma (,).','From address'=>'Absenderadresse','Leave empty to use the WordPress default. Only set an address at a domain this site is allowed to send mail for.'=>'Leer lassen, um die WordPress-Standardadresse zu verwenden. Gib nur eine Adresse mit einer Domain an, für die diese Website E-Mails versenden darf.','Reply-To address'=>'Antwortadresse (Reply-To)','Format'=>'Format','Plain text'=>'Nur Text','HTML'=>'HTML','Subject prefix'=>'Betreff-Präfix','One or more email addresses to send to are invalid.'=>'Eine oder mehrere Empfängeradressen sind ungültig.','Enter at least one valid email address to send to.'=>'Gib mindestens eine gültige E-Mail-Adresse als Empfänger ein.','The email address is invalid.'=>'Die E-Mail-Adresse ist ungültig.','The format must be plain text or HTML.'=>'Das Format muss „Nur Text“ oder HTML sein.','No email address to send to is set.'=>'Es ist keine Empfängeradresse festgelegt.','WP Updates Notifier: test message for %s'=>'WP Updates Notifier: Testnachricht für %s','This is a test message from WP Updates Notifier for %1$s (%2$s). Update notifications for this site will be sent to this address.'=>'Dies ist eine Testnachricht von WP Updates Notifier für %1$s (%2$s). Benachrichtigungen über Aktualisierungen für diese Website werden an diese Adresse gesendet.','WP Updates Notifier: reminder of updates waiting for %s'=>'WP Updates Notifier: Erinnerung an ausstehende Aktualisierungen für %s','WordPress could not send the email.'=>'WordPress konnte die E-Mail nicht senden.','The email could not be sent (%s).'=>'Die E-Mail konnte nicht gesendet werden (%s).']];